/* [Details] */
edge_radius = 0.001; // [0.0001:0.0001:0.01]
line_count = 4; // [2:1:10]
line_width = 0.0005; // [0.0001:0.0001:0.005]
line_spacing = 0.001; // [0.0001:0.0001:0.01]
prism_offset = 0.0005; // [0:0.0001:0.01]

$fn = 64; // [16:8:128]

// Calculate the total width of the line pattern
total_line_width = (line_count - 1) * line_spacing + line_count * line_width;

// Calculate the starting position for the lines
line_start_x = -total_line_width / 2;

// Create the rounded cube (plate base)
rounded_cube() {
    // Create a cube with rounded edges using minkowski
    minkowski() {
        // Base cube
        cube([plate_length, plate_width, plate_thickness], center = true);
        // Spherical cutter for rounding
        sphere(d = edge_radius * 2);
    }
}

// Create the rectangular prism with parallel lines
prism_with_lines() {
    // Create the base prism
    prism_base = cube([prism_length, prism_width, prism_height], center = true);

    // Create the parallel lines
    lines = for (i = [0:line_count-1])
        translate([line_start_x + i * (line_spacing + line_width) + line_width / 2, 0, 0])
            cube([line_width, prism_width, prism_height * 2], center = true);

    // Combine the prism base with the lines
    union() {
        prism_base;
        lines;
    }
}

// Main assembly
difference() {
    // The rounded cube (plate)
    rounded_cube();

    // Cut out the prism with lines, offset from center
    translate([prism_offset, 0, 0])
        prism_with_lines();
}

outer_diameter = 0.285; // [0.05:0.001:5]
inner_diameter = 0.1425; // [0.01:0.001:5]
