length = 358.3; // [10:1:1000]
width = 750; // [10:1:1000]
height = 190.1; // [10:1:500]
scale_factor = 0.75; // [0.1:0.01:2]
taper_ratio = 0.05; // [0:0.01:0.5]

/* [Details] */
$fn = 64; // [16:8:128]

// Calculate scaled dimensions
scaled_length = length * scale_factor;
scaled_width = width * scale_factor;

// Calculate taper dimensions
taper_length = scaled_length * taper_ratio;
taper_width = scaled_width * taper_ratio;

// Create the tapered box using a hull of two rectangles
module tapered_box() {
    // Bottom rectangle (full size)
    bottom_rect = [
        [-scaled_length/2, -scaled_width/2, 0],
        [scaled_length/2, -scaled_width/2, 0],
        [scaled_length/2, scaled_width/2, 0],
        [-scaled_length/2, scaled_width/2, 0]
    ];

    // Top rectangle (tapered inward)
    top_rect = [
        [-(scaled_length/2 - taper_length/2), -(scaled_width/2 - taper_width/2), height],
        [(scaled_length/2 - taper_length/2), -(scaled_width/2 - taper_width/2), height],
        [(scaled_length/2 - taper_length/2), (scaled_width/2 - taper_width/2), height],
        [-(scaled_length/2 - taper_length/2), (scaled_width/2 - taper_width/2), height]
    ];

    // Create the tapered box using hull
    hull() {
        // Bottom face
        polygon(points = bottom_rect, faces = [[0,1,2,3]]);

        // Top face
        polygon(points = top_rect, faces = [[0,1,2,3]]);
    }
}

